(11, 1, 'kenapa aplikasi isaku saya tidak bisa di buka, keterangan macet lah, gak tau kenapa.. tolong bantu min.', '2.6.0', 3, '2026-03-28 22:33:22', 'pending', '2026-07-04 02:37:08', 'kenapa aplikasi isaku saya tidak bisa di buka keterangan macet lah gak tau kenapa tolong bantu min', 'aplikasi isa buka terang macet tau tolong bantu min', '2026-07-04 02:37:26'),
